/* 1UP Anime — native account tests against a REAL local Supabase stack.
 * Runs against `supabase start` (API :54321, DB :54322):
 *   npm run test:auth:supabase   (or scripts/run-supabase-local.sh)
 * If the local stack is not running, every test is skipped (not faked).
 * Live Supabase (hosted project) is NOT used; live sign-up stays UNVERIFIED
 * until the owner creates the project and pastes the config
 * (see docs/SUPABASE_SETUP.md). Keys below are LOCAL-DEV ONLY: they are
 * generated by `supabase start` and never valid for a hosted project.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';

const API = process.env.SUPABASE_URL || 'http://127.0.0.1:54321';
const ANON = process.env.SUPABASE_ANON_KEY || 'sb_publishable_ACJWlzQHlZjBrEguHvfOxg_3BJgxAaH';

async function stackUp() {
  try {
    const res = await fetch(`${API}/auth/v1/health`, { signal: AbortSignal.timeout(2000) });
    return res.ok;
  } catch { return false; }
}

async function authCall(path, body, token = null) {
  const res = await fetch(`${API}/auth/v1/${path}`, {
    method: 'POST',
    headers: {
      apikey: ANON,
      Authorization: `Bearer ${token || ANON}`,
      'content-type': 'application/json',
    },
    body: JSON.stringify(body),
  });
  return { status: res.status, json: await res.json().catch(() => ({})) };
}

async function rest(table, { method = 'GET', body = null, token = null, query = '' } = {}) {
  // No token = anonymous role: send NO Authorization header. The local
  // stack does not translate the new sb_publishable_ key into a JWT, so
  // sending it as Bearer makes PostgREST answer 401 (PGRST301).
  const headers = {
    apikey: ANON,
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
    'content-type': 'application/json',
    Prefer: 'return=representation',
  };
  const res = await fetch(`${API}/rest/v1/${table}${query}`, {
    method, headers, body: body ? JSON.stringify(body) : undefined,
  });
  return { status: res.status, json: await res.json().catch(() => ({})) };
}

const stamp = () => `t${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

async function signUpUser(t, username, emailDomain = 'ejemplo.com') {
  if (!(await stackUp())) { t.skip('Local Supabase stack is not running (supabase start)'); return null; }
  const suffix = stamp();
  const email = `asta_${suffix}@${emailDomain}`;
  const signed = await authCall('signup', {
    email, password: 'abc12345', data: { username },
  });
  assert.equal(signed.status, 200, JSON.stringify(signed.json));
  assert.ok(signed.json.access_token, JSON.stringify(signed.json));
  assert.ok(signed.json.user?.id, JSON.stringify(signed.json));
  return { ...signed.json, email, username };
}

test('local: sign-up creates the user and the trigger creates the profile', async (t) => {
  const me = await signUpUser(t, `fan_${stamp()}`.replace(/[^a-z0-9_]/g, '').slice(0, 20));
  if (!me) return;
  // Profile row exists (created by the auth.users trigger, not the client).
  const prof = await rest('profiles', { token: me.access_token, query: `?id=eq.${me.user.id}&select=id,username` });
  assert.equal(prof.status, 200, JSON.stringify(prof.json));
  assert.equal(prof.json.length, 1);
  assert.equal(prof.json[0].username, me.username);
  // Usernames are publicly readable (shown next to comments).
  const pub = await rest('profiles', { query: `?id=eq.${me.user.id}&select=username` });
  assert.equal(pub.status, 200);
  assert.equal(pub.json[0]?.username, me.username);
});

test('local: duplicate email and duplicate username are rejected', async (t) => {
  const me = await signUpUser(t, `fan_${stamp()}`.replace(/[^a-z0-9_]/g, '').slice(0, 20));
  if (!me) return;
  const dupEmail = await authCall('signup', {
    email: me.email, password: 'abc12345', data: { username: `otro_${stamp()}`.slice(0, 20) },
  });
  assert.ok([400, 422].includes(dupEmail.status), JSON.stringify(dupEmail.json));
  assert.match(JSON.stringify(dupEmail.json), /already registered|already exists/i);
  // Same username, different email: the trigger rejects it (unique constraint).
  const dupName = await authCall('signup', {
    email: `otro_${stamp()}@ejemplo.com`, password: 'abc12345', data: { username: me.username },
  });
  assert.ok([400, 422, 500].includes(dupName.status), JSON.stringify(dupName.json));
  assert.match(JSON.stringify(dupName.json), /taken|duplicate|Database error/i);
  // The rejected sign-up left no usable account behind.
  const login = await authCall('token?grant_type=password', {
    email: `otro_${stamp()}@ejemplo.com`, password: 'abc12345',
  });
  assert.notEqual(login.status, 200);
});

test('local: sign-in works, wrong password fails, reset email is accepted', async (t) => {
  const me = await signUpUser(t, `fan_${stamp()}`.replace(/[^a-z0-9_]/g, '').slice(0, 20));
  if (!me) return;
  const login = await authCall('token?grant_type=password', {
    email: me.email, password: 'abc12345',
  });
  assert.equal(login.status, 200, JSON.stringify(login.json));
  assert.equal(login.json.user.id, me.user.id);
  const wrong = await authCall('token?grant_type=password', {
    email: me.email, password: 'wrong999',
  });
  assert.equal(wrong.status, 400);
  assert.match(JSON.stringify(wrong.json), /Invalid login credentials/i);
  const reset = await authCall('recover', { email: me.email });
  assert.equal(reset.status, 200, JSON.stringify(reset.json));
});

test('local: bad or reserved usernames fail at sign-up (trigger)', async (t) => {
  if (!(await stackUp())) { t.skip('Local Supabase stack is not running (supabase start)'); return; }
  const bad = await authCall('signup', {
    email: `mal_${stamp()}@ejemplo.com`, password: 'abc12345', data: { username: 'MAL Nombre!' },
  });
  assert.ok([400, 422, 500].includes(bad.status), JSON.stringify(bad.json));
  const reserved = await authCall('signup', {
    email: `res_${stamp()}@ejemplo.com`, password: 'abc12345', data: { username: 'admin' },
  });
  assert.ok([400, 422, 500].includes(reserved.status), JSON.stringify(reserved.json));
});

test('local: RLS blocks writing another user data (profiles + comments)', async (t) => {
  const a = await signUpUser(t, `fan_${stamp()}`.replace(/[^a-z0-9_]/g, '').slice(0, 20));
  if (!a) return;
  const b = await signUpUser(t, `fan_${stamp()}`.replace(/[^a-z0-9_]/g, '').slice(0, 20));
  if (!b) return;
  const tokenA = a.access_token;
  const tokenB = b.access_token;
  // A cannot create a profile row for B (RLS: id must be auth.uid()).
  const forgedProfile = await rest('profiles', {
    method: 'POST', token: tokenA,
    body: { id: b.user.id, username: `falso_${stamp()}`.slice(0, 20) },
  });
  assert.ok([401, 403].includes(forgedProfile.status),
    `expected 401/403, got ${forgedProfile.status}: ${JSON.stringify(forgedProfile.json)}`);
  // A cannot post an episode comment as B (trigger + RLS: author must be self).
  const forgedComment = await rest('oneup_episode_comments', {
    method: 'POST', token: tokenA,
    body: {
      anime_id: 'mal-1', episode_number: 1, author_id: b.user.id,
      display_name: b.username, body: 'Comentario falsificado', status: 'visible',
    },
  });
  assert.ok([401, 403, 500].includes(forgedComment.status),
    `expected 401/403/500, got ${forgedComment.status}: ${JSON.stringify(forgedComment.json)}`);
  // Anonymous (no JWT) cannot insert a comment at all.
  const anonComment = await rest('oneup_episode_comments', {
    method: 'POST', token: null,
    body: {
      anime_id: 'mal-1', episode_number: 1, author_id: a.user.id,
      display_name: a.username, body: 'Comentario anónimo', status: 'visible',
    },
  });
  assert.ok([401, 403].includes(anonComment.status),
    `expected 401/403, got ${anonComment.status}: ${JSON.stringify(anonComment.json)}`);
  // A CAN post their own episode comment (display name comes from the profile).
  const own = await rest('oneup_episode_comments', {
    method: 'POST', token: tokenA,
    body: {
      anime_id: 'mal-1', episode_number: 1, author_id: a.user.id,
      display_name: 'nombre_falso', body: 'Mi comentario real', status: 'visible',
    },
  });
  assert.equal(own.status, 201, JSON.stringify(own.json));
  assert.equal(own.json[0]?.display_name, a.username,
    'trigger must override the client display name with the profile username');
  // A second comment within 45s is rate-limited by the guard trigger.
  const fast = await rest('oneup_episode_comments', {
    method: 'POST', token: tokenA,
    body: {
      anime_id: 'mal-1', episode_number: 1, author_id: a.user.id,
      display_name: a.username, body: 'Demasiado rápido', status: 'visible',
    },
  });
  assert.ok([400, 500].includes(fast.status),
    `expected 400/500, got ${fast.status}: ${JSON.stringify(fast.json)}`);
  assert.match(JSON.stringify(fast.json), /wait before commenting|P0001/i);
  // B can still read the visible comment (public read).
  const visible = await rest('oneup_episode_comments', {
    token: tokenB, query: '?anime_id=eq.mal-1&episode_number=eq.1&status=eq.visible&select=id,display_name,body',
  });
  assert.equal(visible.status, 200);
  assert.ok(visible.json.some((c) => c.body === 'Mi comentario real'));
});

test('local: community post insert is owned, media posts stay pending', async (t) => {
  const a = await signUpUser(t, `fan_${stamp()}`.replace(/[^a-z0-9_]/g, '').slice(0, 20));
  if (!a) return;
  const tokenA = a.access_token;
  const post = await rest('oneup_community_posts', {
    method: 'POST', token: tokenA,
    body: { author_id: a.user.id, kind: 'debate', text: '¿Cuál es el mejor opening?' },
  });
  assert.equal(post.status, 201, JSON.stringify(post.json));
  assert.equal(post.json[0]?.status, 'visible');
  assert.equal(post.json[0]?.display_name, a.username);
  const postId = post.json[0]?.id;
  assert.ok(postId);
  // A cannot change the post status (only moderators via Edge Function).
  const hijack = await rest('oneup_community_posts', {
    method: 'PATCH', token: tokenA, query: `?id=eq.${postId}`,
    body: { status: 'removed' },
  });
  assert.ok([401, 403, 404].includes(hijack.status) || (hijack.status === 200 && hijack.json.length === 0),
    `expected blocked update, got ${hijack.status}: ${JSON.stringify(hijack.json)}`);
  const after = await rest('oneup_community_posts', { token: tokenA, query: `?id=eq.${postId}&select=status` });
  assert.equal(after.json[0]?.status, 'visible');
  // Reaction toggle RPC: like then unlike.
  const like = await rest('rpc/toggle_community_reaction', {
    method: 'POST', token: tokenA, body: { p_post_id: postId },
  });
  assert.equal(like.status, 200, JSON.stringify(like.json));
  assert.equal(like.json, true);
  const unlike = await rest('rpc/toggle_community_reaction', {
    method: 'POST', token: tokenA, body: { p_post_id: postId },
  });
  assert.equal(unlike.status, 200);
  assert.equal(unlike.json, false);
  // Profile update cannot grant verified/owner (guard trigger resets them).
  const prof = await rest('oneup_creator_profiles', {
    method: 'POST', token: tokenA,
    body: { user_id: a.user.id, display_name: a.username, icon: '🔥', avatar_path: '' },
  });
  assert.equal(prof.status, 201, JSON.stringify(prof.json));
  const cheat = await rest('oneup_creator_profiles', {
    method: 'PATCH', token: tokenA, query: `?user_id=eq.${a.user.id}`,
    body: { verified: true, owner: true },
  });
  assert.ok([200, 204].includes(cheat.status), JSON.stringify(cheat.json));
  const afterProf = await rest('oneup_creator_profiles', {
    token: tokenA, query: `?user_id=eq.${a.user.id}&select=verified,owner`,
  });
  assert.equal(afterProf.json[0]?.verified, false);
  assert.equal(afterProf.json[0]?.owner, false);
});

test('local: moderation Edge Functions enforce roles (if functions are serving)', async (t) => {
  const me = await signUpUser(t, `fan_${stamp()}`.replace(/[^a-z0-9_]/g, '').slice(0, 20));
  if (!me) return;
  // Probe: are Edge Functions serving? No JWT -> the gateway answers 401.
  let probe;
  try {
    probe = await fetch(`${API}/functions/v1/moderation-dashboard`, {
      method: 'POST',
      headers: { apikey: ANON, 'content-type': 'application/json' },
      body: '{}',
      signal: AbortSignal.timeout(3000),
    });
  } catch {
    t.skip('Edge Functions are not serving (supabase functions serve)');
    return;
  }
  if (probe.status !== 401) {
    t.skip(`Edge Functions are not serving (probe status ${probe.status})`);
    return;
  }
  const invoke = async (fn, token, body) => {
    const res = await fetch(`${API}/functions/v1/${fn}`, {
      method: 'POST',
      headers: {
        apikey: ANON,
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
        'content-type': 'application/json',
      },
      body: JSON.stringify(body || {}),
    });
    return { status: res.status, json: await res.json().catch(() => ({})) };
  };
  // A regular user cannot open the moderation dashboard.
  const denied = await invoke('moderation-dashboard', me.access_token, {});
  assert.equal(denied.status, 403, JSON.stringify(denied.json));
  assert.match(JSON.stringify(denied.json), /Moderation access required/);
  // No token at all -> the gateway rejects the call.
  const anon = await invoke('moderation-dashboard', null, {});
  assert.equal(anon.status, 401);
  // Anime1v discovery without secrets reports "not configured" (proves routing).
  const a1v = await fetch(`${API}/functions/v1/anime1v-discovery?kind=catalog`, {
    headers: { apikey: ANON },
    signal: AbortSignal.timeout(5000),
  });
  assert.equal(a1v.status, 503, await a1v.text().catch(() => ''));
});
